/* @lc app=leetcode id=3704 lang=kotlin */ class Solution { fun g(ds: List<Int>, i: Int, c: Int, a: Boolean, b: Boolean, memo: HashMap<Int, Long>): Long = if (i == ds.size) (if (c == 0 && !a && !b) 1L else 0L) else memo.getOrPut(((i * 2 + c) * 2 + (if (a) 1 else 0)) * 2 + (if (b) 1 else 0)) { (if (a) 1..9 else 0..0).sumOf { da -> (if (b) 1..9 else 0..0).sumOf { db -> (da + db + c).let { s -> if (s % 10 == ds[i]) listOf(true, false).filter { na -> a || !na }.sumOf { na -> listOf(true, false).filter { nb -> b || !nb }.sumOf { nb -> g(ds, i + 1, s / 10, na, nb, memo) } } else 0L } } } } fun countNoZeroPairs(n: Long): Long = n.toString().reversed().map { it - '0' }.let { ds -> g(ds, 0, 0, true, true, HashMap()) } }